<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { api, ApiError } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'
type Item={id:string;title:string;kind:string;review_status:string;business_status:string;updated_at:string;allowed_actions:string[]}
const items=ref<Item[]>([]);const filter=ref('ALL');const loading=ref(true);const error=ref('')
const visible=computed(()=>filter.value==='ALL'?items.value:items.value.filter(item=>item.review_status===filter.value))
async function load(){try{const response=await api<{data:{items:Item[]}}>('/items/?mine=true&page_size=100');items.value=response.data.items.filter(item=>['DRAFT','PENDING','REJECTED'].includes(item.review_status))}catch(reason){error.value=reason instanceof ApiError?reason.message:'无法读取草稿'}finally{loading.value=false}}
onMounted(load)
</script>
<template><div class="page"><header><p class="eyebrow">P08 · PRIVATE WORKSPACE</p><h1 class="page-title">草稿与审核进度</h1><p class="page-lead">未通过审核的内容只对你和有权协调员可见，不进入公开搜索和匹配索引。</p></header><div class="tabs"><button v-for="entry in [['ALL','全部'],['DRAFT','草稿'],['PENDING','待审'],['REJECTED','被驳回']]" :key="entry[0]" :class="{active:filter===entry[0]}" @click="filter=entry[0]">{{entry[1]}}</button></div><p v-if="loading" class="empty">正在读取你的非公开内容…</p><p v-else-if="error" class="empty error">{{error}}</p><div v-else-if="visible.length" class="draft-list"><article v-for="item in visible" :key="item.id" class="panel draft"><span class="kind">{{item.kind==='LOST'?'遗失':'招领'}}</span><div><h2>{{item.title}}</h2><p>更新于 {{new Date(item.updated_at).toLocaleString('zh-CN')}}</p></div><span class="status-tag">{{item.review_status}}</span><RouterLink class="button button-ghost" :to="`/items/${item.id}`">查看 <AppIcon name="arrow"/></RouterLink></article></div><div v-else class="empty"><AppIcon name="box"/><h2>当前分类没有内容</h2><RouterLink class="button button-brand" to="/publish/lost">新建遗失信息</RouterLink></div></div></template>
<style scoped>.tabs{display:flex;gap:8px;margin:32px 0 20px}.tabs button{padding:10px 16px;color:var(--ct-text-muted);border:1px solid var(--ct-border);border-radius:10px;background:transparent}.tabs button.active{color:var(--ct-brand-ink);background:var(--ct-brand)}.draft-list{display:grid;gap:12px}.draft{display:grid;grid-template-columns:auto 1fr auto auto;gap:18px;align-items:center;padding:20px;box-shadow:none}.draft h2,.draft p{margin:0}.draft p{margin-top:6px;color:var(--ct-text-muted);font-size:12px}.kind{color:var(--ct-brand)}.empty{display:grid;place-items:center;gap:12px;min-height:260px;color:var(--ct-text-muted);border:1px dashed var(--ct-border);border-radius:16px}.error{color:var(--ct-danger)}@media(max-width:650px){.draft{grid-template-columns:auto 1fr}.draft>.status-tag,.draft>.button{grid-column:2}.tabs{overflow:auto}}</style>
